package hu.synostream.android;
import org.json.*;import java.util.*;import java.util.concurrent.*;import java.util.function.*;
/** Library-scoped discovery state. Only TMDB IDs and language are sent to TMDB. */
final class Recommendations {
 static final ExecutorService NETWORK=Executors.newFixedThreadPool(4,r->{Thread t=new Thread(r,"SynoStream-recommendation");t.setDaemon(true);return t;});
 static final long TTL=7*86400000L;final JSONObject state;final Consumer<String> save;final LongSupplier clock;final Random random;
 Recommendations(String json,Consumer<String> persist){this(json,persist,System::currentTimeMillis,new Random());}
 Recommendations(String json,Consumer<String> persist,LongSupplier now,Random rng){JSONObject parsed;try{parsed=new JSONObject(json);}catch(Exception invalid){parsed=new JSONObject();}state=parsed;save=persist;clock=now;random=rng;}
 static List<String> keys(JSONObject o){List<String> keys=new ArrayList<>();Iterator<String> it=o.keys();while(it.hasNext())keys.add(it.next());return keys;}
 static String key(boolean movie,long id){return (movie?"movie/":"tv/")+id;}
 JSONObject object(String name){JSONObject o=state.optJSONObject(name);if(o==null){o=new JSONObject();put(state,name,o);}return o;}
 static void put(JSONObject o,String k,Object v){try{o.put(k,v);}catch(JSONException invalid){throw new IllegalArgumentException(invalid);}}
 synchronized boolean responded(JSONObject item){return object("feedback").has(key(item));}
 synchronized void persist(){save.accept(state.toString());}
 static JSONObject normalize(JSONObject raw,boolean movie,String reason){if(raw==null||raw.optBoolean("adult")||raw.optLong("id")<=0)return null;String title=raw.optString(movie?"title":"name");if(title.isBlank())title=raw.optString(movie?"original_title":"original_name");if(title.isBlank())return null;JSONObject o=new JSONObject();put(o,"id",raw.optLong("id"));put(o,"movie",movie);put(o,"title",title);put(o,"overview",raw.optString("overview"));put(o,"date",raw.optString(movie?"release_date":"first_air_date"));String poster=raw.optString("poster_path");put(o,"poster",poster.matches("/[A-Za-z0-9_-]+\\.(jpg|png|webp)")?"https://image.tmdb.org/t/p/w342"+poster:"");put(o,"reason",reason);return o;}
 static String key(JSONObject o){return key(o.optBoolean("movie"),o.optLong("id"));}
 synchronized Map<String,JSONObject> pool(String language){Map<String,JSONObject> result=new LinkedHashMap<>();JSONObject cache=object("cache");for(String k:keys(cache)){if(!k.startsWith(language+":"))continue;JSONObject active=state.optJSONObject("active");if(active!=null&&!active.has(k.substring(language.length()+1)))continue;JSONObject c=cache.optJSONObject(k);if(c==null||clock.getAsLong()-c.optLong("time")>30*86400000L)continue;JSONArray items=c.optJSONArray("items");if(items==null)continue;for(int i=0;i<items.length();i++){JSONObject item=items.optJSONObject(i);if(item!=null)result.putIfAbsent(key(item),item);}}return result;}
 synchronized List<JSONObject> feedback(String mode,Set<String> owned){List<JSONObject> out=new ArrayList<>();JSONObject f=object("feedback");for(String k:keys(f)){JSONObject e=f.optJSONObject(k);if(e!=null&&mode.equals(e.optString("state"))&&!owned.contains(k)&&e.optJSONObject("item")!=null)out.add(e.optJSONObject("item"));}out.sort(Comparator.comparing(o->o.optString("title")));return out;}
 synchronized void feedback(JSONObject item,String value){JSONObject f=object("feedback");if(value.equals("neutral"))f.remove(key(item));else{JSONObject e=new JSONObject();put(e,"state",value);put(e,"item",item);put(f,key(item),e);}persist();}
 synchronized List<JSONObject> draw(String language,Set<String> owned,Set<String> previous,boolean prefer,int limit){Map<String,JSONObject> pool=pool(language);JSONObject f=object("feedback"),seen=object("seen"),hu=object("hu");List<JSONObject> candidates=new ArrayList<>();for(Map.Entry<String,JSONObject> e:pool.entrySet())if(!owned.contains(e.getKey())&&!f.has(e.getKey())){JSONObject item=e.getValue();JSONObject translation=hu.optJSONObject(e.getKey());put(item,"has_hu",translation!=null&&translation.optBoolean("ok"));if(prefer&&language.startsWith("hu")&&translation!=null&&translation.optBoolean("ok")){if(!translation.optString("title").isBlank())put(item,"title",translation.optString("title"));put(item,"overview",translation.optString("overview"));}candidates.add(item);}
  Collections.shuffle(candidates,random);candidates.sort(Comparator.<JSONObject>comparingInt(o->seen.optInt(key(o))).thenComparingInt(o->previous.contains(key(o))?1:0).thenComparingInt(o->prefer&&!o.optBoolean("has_hu")?1:0));List<JSONObject> out=new ArrayList<>(candidates.subList(0,Math.min(limit,candidates.size())));if(prefer)out.sort(Comparator.comparingInt(o->o.optBoolean("has_hu")?0:1));for(JSONObject item:out)put(seen,key(item),seen.optInt(key(item))+1);persist();return out;
 }
 static final class Outcome {int requests,errors;}
 Outcome load(List<Library.Card> source,boolean movie,String language,boolean prefer,Set<String> owned,Recognition.Api api,BooleanSupplier stop,Runnable progress)throws Exception {
  if(stop.getAsBoolean())throw new InterruptedException();
  LinkedHashMap<Long,Library.Card> seeds=new LinkedHashMap<>();for(Library.Card c:source)if(c.movie==movie&&c.id>0)seeds.put(c.id,c);synchronized(this){for(JSONObject item:feedback("interested",Set.of()))if(item.optBoolean("movie")==movie){Library.Card c=new Library.Card("",item.optString("title"),movie);c.id=item.optLong("id");seeds.putIfAbsent(c.id,c);}}
  synchronized(this){JSONObject active=new JSONObject();for(long id:seeds.keySet())put(active,key(movie,id),true);put(state,"active",active);}
  List<Library.Card> pending=new ArrayList<>();synchronized(this){for(Library.Card c:seeds.values()){JSONObject entry=object("cache").optJSONObject(language+":"+key(movie,c.id));if(entry==null||clock.getAsLong()-entry.optLong("time")>=TTL)pending.add(c);}Collections.shuffle(pending,random);pending.sort(Comparator.comparingLong(c->{JSONObject e=object("cache").optJSONObject(language+":"+key(movie,c.id));return e==null?0:e.optLong("time");}));}if(pending.size()>4)pending=new ArrayList<>(pending.subList(0,4));Outcome outcome=new Outcome();outcome.requests=pending.size();ExecutorService workers=NETWORK;List<Future<Object[]>> futures=new ArrayList<>();
  try{CompletionService<Object[]> tasks=new ExecutorCompletionService<>(workers);for(Library.Card seed:pending)futures.add(tasks.submit(()->{try{return new Object[]{seed,api.get(key(movie,seed.id)+"/recommendations",Map.of("language",language,"page","1"))};}catch(Exception error){return new Object[]{seed,error};}}));
   for(int i=0;i<pending.size();i++){if(stop.getAsBoolean())throw new InterruptedException();Object[] response=tasks.take().get();if(stop.getAsBoolean())throw new InterruptedException();Library.Card seed=(Library.Card)response[0];if(response[1] instanceof Exception){outcome.errors++;continue;}JSONObject raw=(JSONObject)response[1];JSONArray rows=raw.optJSONArray("results");if(rows==null){outcome.errors++;continue;}JSONArray items=new JSONArray();for(int n=0;n<Math.min(rows.length(),60);n++){JSONObject item=normalize(rows.optJSONObject(n),movie,seed.title);if(item!=null)items.put(item);}synchronized(this){JSONObject entry=new JSONObject();put(entry,"time",clock.getAsLong());put(entry,"items",items);JSONObject cache=object("cache");put(cache,language+":"+key(movie,seed.id),entry);while(cache.length()>32){String oldest=keys(cache).stream().min(Comparator.comparingLong(k->cache.optJSONObject(k).optLong("time"))).orElseThrow();cache.remove(oldest);}persist();}progress.run();}
   if(prefer){List<JSONObject> translations; synchronized(this){translations=new ArrayList<>(pool(language).values());Collections.shuffle(translations,random);translations.removeIf(item->{if(owned.contains(key(item)))return true;JSONObject h=object("hu").optJSONObject(key(item));return h!=null&&clock.getAsLong()-h.optLong("time")<TTL;});}if(translations.size()>8)translations=new ArrayList<>(translations.subList(0,8));CompletionService<Object[]> local=new ExecutorCompletionService<>(workers);for(JSONObject item:translations)futures.add(local.submit(()->{try{return new Object[]{item,api.get(key(item)+"/translations",Map.of())};}catch(Exception error){return new Object[]{item,error};}}));for(int i=0;i<translations.size();i++){if(stop.getAsBoolean())throw new InterruptedException();Object[] response=local.take().get();if(stop.getAsBoolean())throw new InterruptedException();if(response[1] instanceof Exception)continue;JSONObject item=(JSONObject)response[0],entry=new JSONObject();JSONArray rows=((JSONObject)response[1]).optJSONArray("translations");if(rows==null)continue;put(entry,"time",clock.getAsLong());put(entry,"ok",false);for(int n=0;n<rows.length();n++){JSONObject t=rows.optJSONObject(n),d=t==null?null:t.optJSONObject("data");if(t!=null&&"hu".equals(t.optString("iso_639_1"))&&d!=null&&!d.optString("overview").isBlank()){put(entry,"ok",true);put(entry,"title",d.optString(item.optBoolean("movie")?"title":"name"));put(entry,"overview",d.optString("overview"));break;}}synchronized(this){put(object("hu"),key(item),entry);persist();}}}
   if(stop.getAsBoolean())throw new InterruptedException();return outcome;
  }finally{for(Future<?> future:futures)future.cancel(true);}
 }
}
